// Fetch Vietnam bilateral export data from UN COMTRADE API
// Reporter: 704 (Vietnam), Flow: X (Export)
// Commodities: Rice(1006), Coffee(0901), Pepper(0904), Rubber(4001), Cassava(0714)
// Partners: World(0), China(156), USA(840), Japan(392), Korea(410), Philippines(608), Indonesia(360), Malaysia(458), Germany(276), India(356)

const API_KEY = $env.COMTRADE_API_KEY;
const BASE_URL = 'https://comtradeapi.un.org/data/v1/get/C/A/HS';

// Partner code to name mapping
const PARTNERS = {
  0: 'World', 156: 'China', 840: 'USA', 392: 'Japan',
  410: 'Korea', 608: 'Philippines', 360: 'Indonesia',
  458: 'Malaysia', 276: 'Germany', 356: 'India'
};

// HS code to commodity mapping
const COMMODITIES = {
  '1006': 'Rice', '0901': 'Coffee', '0904': 'Pepper',
  '4001': 'Rubber', '0714': 'Cassava'
};

const partnerCodes = Object.keys(PARTNERS).join(',');
const cmdCodes = Object.keys(COMMODITIES).join(',');
const rows = [];

try {
  // Fetch latest 2 years to maximize data availability
  const url = `${BASE_URL}?reporterCode=704&flowCode=X&cmdCode=${cmdCodes}&partnerCode=${partnerCodes}&period=2023,2024,2025&subscription-key=${API_KEY}`;
  const response = await fetch(url);
  const result = await response.json();

  if (result.data && Array.isArray(result.data)) {
    // Filter: only motCode=0 (all modes of transport) to avoid duplicates
    const filtered = result.data.filter(r => r.motCode === 0 || r.motCode === null);

    // Group by commodity+partner, keep latest year
    const groupMap = {};
    for (const item of filtered) {
      const key = `${item.cmdCode}_${item.partnerCode}`;
      const year = parseInt(item.period);
      if (!groupMap[key] || year > groupMap[key].year) {
        groupMap[key] = {
          year,
          cmdCode: item.cmdCode,
          partnerCode: item.partnerCode,
          fobValue: item.fobvalue || item.primaryValue || 0,
          netWgt: item.netWgt || 0
        };
      }
    }

    for (const [key, data] of Object.entries(groupMap)) {
      const commodity = COMMODITIES[data.cmdCode] || data.cmdCode;
      const partner = PARTNERS[data.partnerCode] || `Country_${data.partnerCode}`;
      const valueMillionUSD = Math.round(data.fobValue / 1000000 * 100) / 100;
      const weightTonnes = Math.round(data.netWgt / 1000);

      // Export value in million USD
      rows.push({
        source: 'COMTRADE',
        commodity: commodity,
        metric: `export_value_to_${partner.toLowerCase()}`,
        value: valueMillionUSD,
        unit: 'million_USD',
        period: String(data.year)
      });

      // Export volume in tonnes (only if > 0)
      if (weightTonnes > 0) {
        rows.push({
          source: 'COMTRADE',
          commodity: commodity,
          metric: `export_volume_to_${partner.toLowerCase()}`,
          value: weightTonnes,
          unit: 'tonnes',
          period: String(data.year)
        });
      }
    }
  }
} catch (e) {
  // API error fallback
}

if (rows.length === 0) {
  return [{ json: { source: 'COMTRADE', commodity: 'Rice', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}

return rows.map(r => ({ json: r }));
